using System;using System.Collections.Generic;using UnityEngine;using Exoduser.UnityPort.Core;
namespace Exoduser.UnityPort {public sealed partial class NativeSkillView {
 sealed class BladeMesh {public GameObject Go;public Mesh Mesh;public MeshRenderer Renderer;public int Tick=-1;public readonly List<Vector3> Vertices=new List<Vector3>(2048);public readonly List<Color> Colors=new List<Color>(2048);public readonly List<int> Indices=new List<int>(4096);}
 readonly Dictionary<int,BladeMesh> bladeMeshes=new Dictionary<int,BladeMesh>();readonly List<int> deadBladeMeshes=new List<int>();public int ActivePlayerBladeViews{get;private set;}
 void UpdatePlayerBladeViews(Simulation sim,float time){deadBladeMeshes.Clear();foreach(int key in bladeMeshes.Keys)deadBladeMeshes.Add(key);ActivePlayerBladeViews=0;foreach(var p in sim.PlayerSkillProjectiles){if(!p.Active||!(p.MhBlade||p.PlagueBlade))continue;deadBladeMeshes.Remove(p.Id);if(!bladeMeshes.TryGetValue(p.Id,out var b)){b=new BladeMesh{Go=new GameObject("웹 칼날 "+p.Id),Mesh=new Mesh{name="원문 칼날/잔상 도형"}};b.Go.transform.SetParent(parent,false);b.Go.AddComponent<MeshFilter>().sharedMesh=b.Mesh;b.Renderer=b.Go.AddComponent<MeshRenderer>();b.Renderer.sharedMaterial=malice;bladeMeshes[p.Id]=b;}ActivePlayerBladeViews++;b.Go.transform.position=NativeRemodel3D.Point(p.X,p.Y);float a=(float)Math.Atan2(p.Vy,p.Vx);b.Go.transform.rotation=(NativeRemodel3D.Active?Quaternion.Euler(NativeRemodel3D.Pitch*Mathf.Rad2Deg,0,0):Quaternion.identity)*Quaternion.Euler(0,0,-a*Mathf.Rad2Deg);b.Renderer.sortingOrder=(int)p.Y+1;
 if(b.Tick==sim.TickCount)continue;b.Tick=sim.TickCount;double cs=Math.Cos(-a),sn=Math.Sin(-a);var trail=new double[p.TrailLength][];for(int i=0;i<trail.Length;i++){int idx=(p.TrailHead-1-i+p.TrailX.Length)%p.TrailX.Length;double dx=p.TrailX[idx]-p.X,dy=p.TrailY[idx]-p.Y;trail[i]=new[]{dx*cs-dy*sn,dx*sn+dy*cs};}var input=new BladeVisualInput{Kind=p.VenomBlade?"venom":p.LtnChaser?"lightning":p.PlagueBlade?"plague":"blade",X=p.X,Y=p.Y,Time=time*1000,Fade=Math.Min(1,1-p.Dist/p.MaxDist*.3),Fused=p.MhFused,Trail=trail};b.Vertices.Clear();b.Colors.Clear();b.Indices.Clear();foreach(var path in PlayerBladeVisuals.Build(input)){Color color;ColorUtility.TryParseHtmlString(path.Color,out color);color.a=(float)path.Alpha;color=color.linear;var v=path.Points;if(path.Kind=="ellipse")BladeEllipse(b,v[0],v[1],v[2],v[3],color);else if(path.Kind=="fill")BladePolygon(b,v,color);else BladeStroke(b,v,path.Width,path.Round,color);}b.Mesh.Clear();b.Mesh.SetVertices(b.Vertices);b.Mesh.SetColors(b.Colors);b.Mesh.SetTriangles(b.Indices,0);b.Mesh.RecalculateBounds();}
 foreach(int key in deadBladeMeshes){var b=bladeMeshes[key];UnityEngine.Object.Destroy(b.Mesh);UnityEngine.Object.Destroy(b.Go);bladeMeshes.Remove(key);}}
 static int BladeVertex(BladeMesh b,double x,double y,Color color){int index=b.Vertices.Count;b.Vertices.Add(new Vector3((float)x/100,-(float)y/100,0));b.Colors.Add(color);return index;}
 static void BladeTri(BladeMesh b,int a,int c,int d){b.Indices.Add(a);b.Indices.Add(c);b.Indices.Add(d);}
 static void BladePolygon(BladeMesh b,double[] points,Color color){int n=points.Length/2,start=b.Vertices.Count;for(int i=0;i<n;i++)BladeVertex(b,points[i*2],points[i*2+1],color);for(int i=1;i<n-1;i++)BladeTri(b,start,start+i,start+i+1);}
 static void BladeEllipse(BladeMesh b,double x,double y,double rx,double ry,Color color){int segments=32,start=BladeVertex(b,x,y,color);for(int i=0;i<segments;i++){double a=i*2*Math.PI/segments;BladeVertex(b,x+Math.Cos(a)*rx,y+Math.Sin(a)*ry,color);}for(int i=0;i<segments;i++)BladeTri(b,start,start+1+i,start+1+(i+1)%segments);}
 static void BladeStroke(BladeMesh b,double[] points,double width,bool round,Color color){int n=points.Length/2,start=b.Vertices.Count;double half=width/2;for(int i=0;i<n;i++){double x=points[i*2],y=points[i*2+1],px=0,py=0,nx=0,ny=0;if(i>0){double dx=x-points[(i-1)*2],dy=y-points[(i-1)*2+1],len=Math.Sqrt(dx*dx+dy*dy);if(len>0){px=-dy/len;py=dx/len;}}if(i+1<n){double dx=points[(i+1)*2]-x,dy=points[(i+1)*2+1]-y,len=Math.Sqrt(dx*dx+dy*dy);if(len>0){nx=-dy/len;ny=dx/len;}}if(i==0){px=nx;py=ny;}if(i==n-1){nx=px;ny=py;}double mx=px+nx,my=py+ny,ml=Math.Sqrt(mx*mx+my*my);if(ml>0){mx/=ml;my/=ml;}double dot=mx*nx+my*ny,amount=Math.Abs(dot)>1e-6?Math.Min(half/Math.Abs(dot),half*10):half;BladeVertex(b,x+mx*amount,y+my*amount,color);BladeVertex(b,x-mx*amount,y-my*amount,color);}for(int i=0;i<n-1;i++){int j=start+i*2;BladeTri(b,j,j+1,j+2);BladeTri(b,j+2,j+1,j+3);}if(round&&n>0){BladeEllipse(b,points[0],points[1],half,half,color);BladeEllipse(b,points[(n-1)*2],points[(n-1)*2+1],half,half,color);}}
 void ResetPlayerBladeViews(){foreach(var b in bladeMeshes.Values){UnityEngine.Object.Destroy(b.Mesh);UnityEngine.Object.Destroy(b.Go);}bladeMeshes.Clear();ActivePlayerBladeViews=0;}
}}
